import heapq
from collections import Counter


def top_k_frequent(nums: list[int], k: int) -> list[int]:
    heap = []
    for value, n in Counter(nums).items():
        heapq.heappush(heap, (n, value))
        if len(heap) > k:
            heapq.heappop(heap)
    return [value for _, value in heap]
